-- Ties a stored file to an expense as its receipt. The file is one this person stored, in this
-- company, and is not a receipt yet; the expense is one they may see. Posted or cancelled, an
-- expense may be given its receipt: the paper exists either way.
CREATE FUNCTION app.attach_expense_receipt(p_expense uuid, p_file uuid) RETURNS uuid
  LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp
  AS $$
DECLARE
  v_tenant uuid := app.tenant_id();
  v_user uuid := app.current_user_id();
  v_scope uuid[] := app.tenant_branch_ids();
  v_expense public.expenses%ROWTYPE;
  v_file public.files%ROWTYPE;
  v_id uuid;
BEGIN
  IF v_tenant IS NULL OR v_user IS NULL OR app.tenant_role() IS NULL OR app.tenant_role() NOT IN ('owner', 'accountant') THEN
    RAISE EXCEPTION 'this role does not keep the company''s expenses' USING ERRCODE = 'insufficient_privilege';
  END IF;
  IF p_expense IS NULL OR p_file IS NULL THEN
    RAISE EXCEPTION 'no such expense in this company' USING ERRCODE = 'SE334';
  END IF;
  -- One at a time for an expense, so the count below holds.
  PERFORM pg_advisory_xact_lock(hashtextextended('expense_receipts:' || p_expense::text, 0));
  SELECT e.* INTO v_expense FROM public.expenses e WHERE e.tenant_id = v_tenant AND e.id = p_expense;
  IF NOT FOUND OR (v_scope IS NOT NULL AND (v_expense.branch_id IS NULL OR NOT (v_expense.branch_id = ANY (v_scope)))) THEN
    RAISE EXCEPTION 'no such expense in this company' USING ERRCODE = 'SE334';
  END IF;
  SELECT f.* INTO v_file FROM public.files f WHERE f.tenant_id = v_tenant AND f.id = p_file FOR UPDATE;
  IF NOT FOUND OR v_file.created_by IS DISTINCT FROM v_user OR v_file.status <> 'stored'
     OR EXISTS (SELECT 1 FROM public.expense_receipts r WHERE r.tenant_id = v_tenant AND r.file_id = p_file) THEN
    RAISE EXCEPTION 'a receipt is a stored file of the person attaching it, not yet anyone''s receipt' USING ERRCODE = 'SE376';
  END IF;
  IF (SELECT count(*) FROM public.expense_receipts r WHERE r.tenant_id = v_tenant AND r.expense_id = p_expense) >= 10 THEN
    RAISE EXCEPTION 'an expense has at most ten receipts' USING ERRCODE = 'SE377';
  END IF;
  INSERT INTO public.expense_receipts (tenant_id, expense_id, file_id, created_by)
    VALUES (v_tenant, p_expense, p_file, v_user)
    RETURNING id INTO v_id;
  INSERT INTO public.audit_log (tenant_id, actor_user_id, actor_role, action, entity, entity_id, after)
    VALUES (v_tenant, v_user, app.tenant_role(), 'expense_receipt.attach', 'expense', p_expense,
      jsonb_build_object('number', v_expense.number, 'receipt', v_id, 'file', p_file, 'name', v_file.name, 'contentType', v_file.content_type, 'sizeBytes', v_file.size_bytes));
  RETURN v_id;
END $$;
--> statement-breakpoint
REVOKE ALL ON FUNCTION app.attach_expense_receipt(uuid, uuid) FROM PUBLIC;
--> statement-breakpoint
GRANT EXECUTE ON FUNCTION app.attach_expense_receipt(uuid, uuid) TO app_runtime;
--> statement-breakpoint
