CREATE FUNCTION app.audit_reserved_expense_receipt(p_action text) RETURNS boolean
  LANGUAGE sql IMMUTABLE SET search_path = pg_catalog, pg_temp
  AS $$ SELECT p_action IN ('expense_receipt.attach') $$;
