-- ── hand-written: an accountant keeps receipts ──────────────────────────────────────────────────
-- Beside the policies of 0002 (the owner stores, the owner and the auditor read), which stay as
-- they are. An accountant stores a file of their own, marks it stored, and reads a file that is
-- their own or is the receipt of an expense they may see.
--
-- Whether a file is such a receipt is asked through a function, not a subquery: a subquery on
-- expense_receipts here would be read under that table's own policy.
CREATE FUNCTION app.receipt_file_visible(p_tenant uuid, p_file uuid) RETURNS boolean
  LANGUAGE sql STABLE SECURITY DEFINER SET search_path = pg_catalog, pg_temp
  AS $$
    SELECT p_tenant = app.tenant_id() AND app.tenant_role() IN ('owner', 'accountant', 'auditor') AND EXISTS (
      SELECT 1 FROM public.expense_receipts r
      JOIN public.expenses e ON e.tenant_id = r.tenant_id AND e.id = r.expense_id
      WHERE r.tenant_id = p_tenant AND r.file_id = p_file
        AND (app.tenant_branch_ids() IS NULL OR e.branch_id = ANY (app.tenant_branch_ids())))
  $$;
--> statement-breakpoint
REVOKE ALL ON FUNCTION app.receipt_file_visible(uuid, uuid) FROM PUBLIC;
--> statement-breakpoint
GRANT EXECUTE ON FUNCTION app.receipt_file_visible(uuid, uuid) TO app_runtime;
--> statement-breakpoint
